from __future__ import annotations


class OrderService:
    def __init__(self, a, b, c, d, e, f) -> None:  # ARCH-030: 6 ctor params
        ...

    def cancel(self, cmd) -> None:  # ARCH-033: commits outside a UoW block
        order = self._orders.get(cmd.id)
        order.cancel()
        self._orders.session.commit()

    def m1(self) -> None: ...
    def m2(self) -> None: ...
    def m3(self) -> None: ...
    def m4(self) -> None: ...
    def m5(self) -> None: ...
    def m6(self) -> None: ...
    def m7(self) -> None: ...
    def m8(self) -> None: ...
